VIVO_MODEL_COLS = [
    "VIVO Y05 4G 4/64GB", "VIVO Y05 4G 4/128GB", "VIVO Y11D 4G 4/128GB",
    "VIVO Y31D 4G 6/128GB", "VIVO Y31D 4G 6/256GB",
]
VIVO_COMPANY_UNLOCK_TARGET = 3000   # company-wide units needed before TOP 3 AM prizes unlock
VIVO_AM_ELIGIBILITY_PCT = 0.80      # AM must reach this % of their own area target
VIVO_PERIOD_LABEL = "1-30 Sep 2026"
VIVO_PRIZES = [8000, 4000, 2000]    # THB for rank 1 / 2 / 3

def export_vivo_gameplan(target_xlsx_path, tsm_df):
    """Reads Target_VIVO_Game_Plan.xlsx ('Sheet1': one row per shop with a
    target for each of the 5 Game Plan model variants) and matches it
    against actual September HANDSET sales of those same variants (the
    variant -- e.g. "4/64GB" -- is parsed out of TSM's DESCRIPTION column
    since CUSTOM_MODEL alone doesn't carry the storage size). Returns
    (shop_records, daily_actual, daily_detail):
    - shop_records: one row per shop with target/actual totals (period
      aggregate, used for the AM ranking and shop table).
    - daily_actual: company-wide [{date, qty}] series (ALL shops, even
      ones not on the 243-shop target list) -- feeds the pace chart and
      the true company-wide unlock check.
    - daily_detail: [{date, shop, region, area, am, model, qty}] -- one
      row per (date, shop, model) for the 243 target-list shops only, so
      the per-model daily trend chart can be filtered by Region/AM/Area/
      Shop.
    Returns ([], [], []) if the target file isn't found, so the
    dashboard still builds."""
    if not target_xlsx_path or not os.path.exists(target_xlsx_path):
        return [], [], []

    target_df = pd.read_excel(target_xlsx_path, sheet_name="Sheet1")
    target_df["SHOP_NAME"] = target_df["SHOP_NAME"].astype(str).str.strip()
    shop_meta = {
        r["SHOP_NAME"]: {"region": r["Region"], "area": r["Area"], "am": str(r["AM Name"]).strip()}
        for _, r in target_df.iterrows()
    }

    # ---- Derive variant-level actuals from TSM ----
    h = tsm_df[(tsm_df["CUSTOM_PRODGROUP"] == "HANDSET") & (tsm_df["CUSTOM_BRAND"] == "VIVO")].copy()
    h = h[h["CUSTOM_MODEL"].isin(["VIVO Y05 4G", "VIVO Y11D 4G", "VIVO Y31D 4G"])]

    def variant_label(row):
        m = re.search(r"(\d+/\d+)", str(row["DESCRIPTION"]))
        if not m:
            return None
        storage = m.group(1)
        return f"{row['CUSTOM_MODEL']} {storage}GB"

    h["variant"] = h.apply(variant_label, axis=1)
    h = h.dropna(subset=["variant"])
    h["SHOP NAME"] = h["SHOP NAME"].astype(str).str.strip()
    h["DATE"] = pd.to_datetime(h["DATE"])

    # Company-wide daily actual (all 5 variants, all shops -- used for the trend chart)
    daily = h.groupby(h["DATE"].dt.strftime("%Y-%m-%d"))["QTY"].sum().reset_index()
    daily_actual = [{"date": r["DATE"], "qty": int(r["QTY"])} for _, r in daily.iterrows()]

    # Per (shop, variant) actual totals for the whole period so far
    per_shop_variant = h.groupby(["SHOP NAME", "variant"])["QTY"].sum().to_dict()

    shop_records = []
    for _, r in target_df.iterrows():
        shop = r["SHOP_NAME"]
        targets = {col: float(r[col]) for col in VIVO_MODEL_COLS}
        actuals = {col: int(per_shop_variant.get((shop, col), 0)) for col in VIVO_MODEL_COLS}
        shop_records.append({
            "area": r["Area"],
            "am": str(r["AM Name"]).strip(),
            "region": r["Region"],
            "shop": shop,
            "targets": targets,
            "targetTotal": round(float(r["Grand Total"]), 2),
            "actuals": actuals,
            "actualTotal": sum(actuals.values()),
        })

    # Per (date, shop, variant) detail for the filterable daily-by-model trend chart
    h_matched = h[h["SHOP NAME"].isin(shop_meta.keys())]
    grp = h_matched.groupby([h_matched["DATE"].dt.strftime("%Y-%m-%d"), "SHOP NAME", "variant"])["QTY"].sum().reset_index()
    daily_detail = []
    for _, r in grp.iterrows():
        meta = shop_meta[r["SHOP NAME"]]
        daily_detail.append({
            "date": r["DATE"],
            "shop": r["SHOP NAME"],
            "region": meta["region"],
            "area": meta["area"],
            "am": meta["am"],
            "model": r["variant"],
            "qty": int(r["QTY"]),
        })

    return shop_records, daily_actual, daily_detail

def export_ip18_target(target_xlsx_path):
    """Reads Target_iP18_By_Shop.xlsx ('Target iP18' sheet: one row per
    shop with a Prebook target) and returns a flat list of records. This
    is a TARGET-ONLY allocation (no actual sales data exists yet -- the
    iPhone 18 hasn't launched in the TSM data), so the tab it feeds is a
    target breakdown/drill-down dashboard rather than an actual-vs-target
    tracker. Returns [] if the file isn't found."""
    if not target_xlsx_path or not os.path.exists(target_xlsx_path):
        return []
    df = pd.read_excel(target_xlsx_path, sheet_name="Target iP18")
    records = []
    for _, r in df.iterrows():
        records.append({
            "code": str(r["CODE WW"]),
            "shop": str(r["SHOP NAME"]).strip(),
            "area": r["Area"],
            "type": str(r["SHOP_TYPE"]).strip(),
            "region": r["Region"],
            "target": int(r["Total"]),
        })
    return records

def build(xlsx_path: str, out_path: str, shop_list_path: str = None, sheep_xlsx_path: str = None, contest_xlsx_path: str = None, retention_roster_path: str = None, vivo_target_path: str = None, ip18_target_path: str = None):
    df = pd.read_excel(xlsx_path, sheet_name="TSM")

    handset_records, handset_f = export_group(df, "HANDSET", rev_col="PRICE")
    accessories_records, accessories_f = export_group(df, "ACCESSORIES", rev_col="PRICE")

    area_to_region = df.drop_duplicates(subset=["AREA"]).set_index("AREA")["REGION"].to_dict()
    shop_lookup = {
        str(r["SHOP_CODE"]): {"shop": str(r["SHOP NAME"]).strip(), "type": r["TYPE SHOP"], "region": r["REGION"], "area": r["AREA"]}
        for _, r in df.drop_duplicates(subset=["SHOP_CODE"]).iterrows()
    }

    if sheep_xlsx_path is None:
        default_sheep = os.path.join(os.path.dirname(os.path.abspath(xlsx_path)), "Sheep_Report.xlsx")
        sheep_xlsx_path = default_sheep if os.path.exists(default_sheep) else "Sheep_Report.xlsx"
    sheep_records, sheep_f = export_sheep(sheep_xlsx_path, area_to_region)

    if retention_roster_path is None:
        contest_dir = os.path.dirname(os.path.abspath(xlsx_path))
        for fn in os.listdir(contest_dir):
            if "retention" in fn.lower() or "staff_retention" in fn.lower():
                retention_roster_path = os.path.join(contest_dir, fn)
                break
    external_roster = load_retention_roster(retention_roster_path, shop_lookup)
    retchpn1_records, retchpn1_roster = export_emp_type(df, "Ret_chpn_1", external_roster=external_roster)

    if contest_xlsx_path is None:
        default_contest_glob = None
        contest_dir = os.path.dirname(os.path.abspath(xlsx_path))
        for fn in os.listdir(contest_dir):
            if "มงคล" in fn or "mongkol" in fn.lower():
                default_contest_glob = os.path.join(contest_dir, fn)
                break
        contest_xlsx_path = default_contest_glob
    mongkol_records, mongkol_data_as_of = export_mongkol(contest_xlsx_path, area_to_region)

    if vivo_target_path is None:
        vivo_dir = os.path.dirname(os.path.abspath(xlsx_path))
        for fn in os.listdir(vivo_dir):
            if "vivo" in fn.lower() and "target" in fn.lower():
                vivo_target_path = os.path.join(vivo_dir, fn)
                break
    vivo_shop_records, vivo_daily, vivo_daily_detail = export_vivo_gameplan(vivo_target_path, df)

    if ip18_target_path is None:
        ip18_dir = os.path.dirname(os.path.abspath(xlsx_path))
        for fn in os.listdir(ip18_dir):
            if "ip18" in fn.lower() or "ip 18" in fn.lower():
                ip18_target_path = os.path.join(ip18_dir, fn)
                break
    ip18_records = export_ip18_target(ip18_target_path)

    handset_json = json.dumps(handset_records, ensure_ascii=False)
    accessories_json = json.dumps(accessories_records, ensure_ascii=False)
    sheep_json = json.dumps(sheep_records, ensure_ascii=False)
    shops_json = load_shops_master(shop_list_path, df)
    targets_json = json.dumps(ENTRY_MODEL_TARGETS, ensure_ascii=False)
    retchpn1_json = json.dumps(retchpn1_records, ensure_ascii=False)
    retchpn1_roster_json = json.dumps(retchpn1_roster, ensure_ascii=False)
    mongkol_json = json.dumps(mongkol_records, ensure_ascii=False)
    vivo_shops_json = json.dumps(vivo_shop_records, ensure_ascii=False)
    vivo_daily_json = json.dumps(vivo_daily, ensure_ascii=False)
    vivo_daily_detail_json = json.dumps(vivo_daily_detail, ensure_ascii=False)
    vivo_models_json = json.dumps(VIVO_MODEL_COLS, ensure_ascii=False)
    vivo_config_json = json.dumps({
        "companyUnlockTarget": VIVO_COMPANY_UNLOCK_TARGET,
        "amEligibilityPct": VIVO_AM_ELIGIBILITY_PCT,
        "periodLabel": VIVO_PERIOD_LABEL,
        "prizes": VIVO_PRIZES,
    }, ensure_ascii=False)
    ip18_json = json.dumps(ip18_records, ensure_ascii=False)

    html = (
        TEMPLATE
        .replace("__CSS__", CSS)
        .replace("__BODY__", BODY)
        .replace("__HANDSET_DATA__", handset_json)
        .replace("__ACCESSORIES_DATA__", accessories_json)
        .replace("__SHEEP_DATA__", sheep_json)
        .replace("__SHOPS__", shops_json)
        .replace("__ENTRY_MODEL_TARGETS__", targets_json)
        .replace("__ENTRY_MODEL_MONTH_DAYS__", json.dumps(ENTRY_MODEL_MONTH_DAYS))
        .replace("__ENTRY_MODEL_MONTH_LABEL__", json.dumps(ENTRY_MODEL_MONTH_LABEL))
        .replace("__RETCHPN1_DATA__", retchpn1_json)
        .replace("__RETCHPN1_ROSTER__", retchpn1_roster_json)
        .replace("__MONGKOL_DATA__", mongkol_json)
        .replace("__MONGKOL_DATA_AS_OF__", json.dumps(mongkol_data_as_of))
        .replace("__VIVO_SHOPS__", vivo_shops_json)
        .replace("__VIVO_DAILY__", vivo_daily_json)
        .replace("__VIVO_DAILY_DETAIL__", vivo_daily_detail_json)
        .replace("__VIVO_MODELS__", vivo_models_json)
        .replace("__VIVO_CONFIG__", vivo_config_json)
        .replace("__IP18_DATA__", ip18_json)
        .replace("__JS__", JS)
    )
    with open(out_path, "w", encoding="utf-8") as fh:
        fh.write(html)

    n_shops_master = len(json.loads(shops_json))
    type_shop_counts = df["TYPE SHOP"].value_counts().to_dict()

    handset_f_all = df[df["CUSTOM_PRODGROUP"] == "HANDSET"]
    entry_actuals = []
    for t in ENTRY_MODEL_TARGETS:
        qty = handset_f_all[(handset_f_all["CUSTOM_BRAND"] == t["brand"]) & (handset_f_all["CUSTOM_MODEL"] == t["model"])]["QTY"].sum()
        entry_actuals.append((t["label"], int(qty), t["target"]))

    print(f"OK -> {out_path}")
    print(f"    Handset:     {len(handset_records)} rows | {handset_f['QTY'].sum():,} units | {handset_f['PRICE'].sum():,} THB (Price)")
    print(f"    Accessories: {len(accessories_records)} rows | {accessories_f['QTY'].sum():,} units | {accessories_f['PRICE'].sum():,} THB (Price)")
    if sheep_f is not None:
        print(f"    Sheep:       {len(sheep_records)} rows | {sheep_f['QTY'].sum():,.0f} units | {sheep_f['NET_AMOUNT'].sum():,.2f} THB  (from {sheep_xlsx_path})")
    else:
        print(f"    Sheep:       0 rows -- {sheep_xlsx_path} not found, Sheep page will show 0s")
    print(f"    Shop master list: {n_shops_master} shops ({'from file' if shop_list_path else 'derived from TSM sheet'})")
    print(f"    TYPE SHOP breakdown (all included): {type_shop_counts}")
    print(f"    Ret_chpn_1: {len(retchpn1_records)} handset rows | {len(retchpn1_roster)} employees in roster ({'from List_Staff_Retention.xlsx' if external_roster else 'derived from TSM sheet'})")
    print(f"    Entry Model vs Target ({ENTRY_MODEL_MONTH_LABEL}):")
    total_actual = sum(a for _, a, _ in entry_actuals)
    total_target = sum(t for _, _, t in entry_actuals)
    for label, actual, target in entry_actuals:
        pct = (actual / target * 100) if target else 0
        print(f"      {label:<20} {actual:>6,} / {target:>6,}  ({pct:5.1f}%)")
    print(f"      {'TOTAL':<20} {total_actual:>6,} / {total_target:>6,}  ({total_actual/total_target*100:5.1f}%)")
    if mongkol_records:
        eligible = sum(1 for r in mongkol_records if r["sepActual"] > r["augBaseline"])
        print(f"    Mongkol Number contest: {len(mongkol_records)} participants | data as of {mongkol_data_as_of} | {eligible} currently exceeded their Aug baseline")
    else:
        print(f"    Mongkol Number contest: 0 participants -- roster file not found, tab will show 0s")
    if vivo_shop_records:
        vivo_total_target = sum(r["targetTotal"] for r in vivo_shop_records)
        vivo_total_actual = sum(r["actualTotal"] for r in vivo_shop_records)
        n_am = len(set(r["am"] for r in vivo_shop_records))
        print(f"    Vivo Game Plan: {len(vivo_shop_records)} shops | {n_am} AMs | {vivo_total_actual:,.0f} / {vivo_total_target:,.0f} units ({vivo_total_actual/vivo_total_target*100:.1f}%) | company unlock at {VIVO_COMPANY_UNLOCK_TARGET:,} units")
    else:
        print(f"    Vivo Game Plan: 0 shops -- Target_VIVO_Game_Plan.xlsx not found, tab will show 0s")
    if ip18_records:
        ip18_total = sum(r["target"] for r in ip18_records)
        print(f"    TG Pre iP18: {len(ip18_records)} shops | {ip18_total:,} units total target")
    else:
        print(f"    TG Pre iP18: 0 shops -- Target_iP18_By_Shop.xlsx not found, tab will show 0s")

if __name__ == "__main__":
    xlsx_path = sys.argv[1] if len(sys.argv) > 1 else "Refresh_TSM.xlsx"
    out_path = sys.argv[2] if len(sys.argv) > 2 else "Handset_Sales_Dashboard.html"
    shop_list_path = sys.argv[3] if len(sys.argv) > 3 and sys.argv[3] else None
    sheep_xlsx_path = sys.argv[4] if len(sys.argv) > 4 and sys.argv[4] else None
    contest_xlsx_path = sys.argv[5] if len(sys.argv) > 5 and sys.argv[5] else None
    retention_roster_path = sys.argv[6] if len(sys.argv) > 6 and sys.argv[6] else None
    vivo_target_path = sys.argv[7] if len(sys.argv) > 7 and sys.argv[7] else None
    ip18_target_path = sys.argv[8] if len(sys.argv) > 8 and sys.argv[8] else None
    build(xlsx_path, out_path, shop_list_path, sheep_xlsx_path, contest_xlsx_path, retention_roster_path, vivo_target_path, ip18_target_path)
